    "hero": null,
    "heroSrc": "/images/blog/commercial-renovation-cost-per-square/commercial-renovation-cost-per-880.6d40ef15.webp",
    "heroSrcSet": "/images/blog/commercial-renovation-cost-per-square/commercial-renovation-cost-per-480.fadf6a0c.webp 480w, /images/blog/commercial-renovation-cost-per-square/commercial-renovation-cost-per-880.6d40ef15.webp 880w, /images/blog/commercial-renovation-cost-per-square/commercial-renovation-cost-per-1320.b802bb9e.webp 1320w",
