    "heroAvifSrcSet": "/images/blog/flight-to-quality-office-winnipeg/skywalk-or-sidelined-how-the-flight-480.f0d60acd.avif 480w, /images/blog/flight-to-quality-office-winnipeg/skywalk-or-sidelined-how-the-flight-880.504162d8.avif 880w, /images/blog/flight-to-quality-office-winnipeg/skywalk-or-sidelined-how-the-flight-1320.98d8ea31.avif 1320w",
